   ```c
   #define SUCCESS 0
   #define ERROR_FILE_NOT_FOUND -1
   #define ERROR_INVALID_PARAMETER -2
   #define ERROR_OUT_OF_MEMORY -3
   ```

2. **Use Functions to Return Errors**: When a function encounters an error, it should return the appropriate error code. This allows the calling function to check the return value and handle the error accordingly.

   ```c
   int open_file(const char *filename) {
       FILE *file = fopen(filename, "r");
       if (file == NULL) {
           return ERROR_FILE_NOT_FOUND;
       }
       // File opened successfully
       return SUCCESS;
   }
   ```

3. **Error Handling in Calling Functions**: The calling function should check the return value of the function that might have failed. Based on the return value, it can decide how to handle the error, such as printing an error message or taking corrective action.

   ```c
   int main() {
       int result = open_file("example.txt");
       if (result == ERROR_FILE_NOT_FOUND) {
           printf("Error: File not found.\n");
       } else if (result == ERROR_INVALID_PARAMETER) {
           printf("Error: Invalid parameter.\n");
       } else if (result == ERROR_OUT_OF_MEMORY) {
           printf("Error: Out of memory.\n");
       } else if (result == SUCCESS) {
           // Continue with file operations
       }
       return 0;
   }
   ```

4. **Use of `errno` for System Errors**: For system calls, you can use the `errno` variable to capture error codes provided by the operating system. This is particularly useful for functions like `fopen`, `malloc`, etc.

   ```c
   #include <errno.h>
   #include <stdio.h>
   #include <stdlib.h>

   int open_file(const char *filename) {
       FILE *file = fopen(filename, "r");
       if (file == NULL) {
           perror("Failed to open file");
           return ERROR_FILE_NOT_FOUND;
       }
       // File opened successfully
       return SUCCESS;
   }
   ```

5. **Custom Error Messages**: For more detailed error handling, you can create a function to print custom error messages based on the error code.

   ```c
   void print_error(int error_code) {
       switch (error_code) {
           case ERROR_FILE_NOT_FOUND:
               printf("Error: File not found.\n");
               break;
           case ERROR_INVALID_PARAMETER:
               printf("Error: Invalid parameter.\n");
               break;
           case ERROR_OUT_OF_MEMORY:
               printf("Error: Out of memory.\n");
               break;
           default:
               printf("Unknown error.\n");
               break;
       }
   }
   ```

6. **Using Structs for Complex Errors**: For more complex error handling, especially in larger projects, consider using structs to encapsulate error information.

   ```c
   typedef struct {
       int code;
       const char *message;
   } Error;

   Error get_error(int code) {
       switch (code) {
           case ERROR_FILE_NOT_FOUND:
               return (Error){ERROR_FILE_NOT_FOUND, "File not found"};
           case ERROR_INVALID_PARAMETER:
               return (Error){ERROR_INVALID_PARAMETER, "Invalid parameter"};
           case ERROR_OUT_OF_MEMORY:
               return (Error){ERROR_OUT_OF_MEMORY, "Out of memory"};
           default:
               return (Error){-1, "Unknown error"};
       }
   }

   void print_error(Error error) {
       printf("Error: %s\n", error.message);
   }
   ```

7. **Using Macros for Error Handling**: Macros can simplify the process of checking return values and handling errors.

   ```c
   #define CHECK(expr) \
       do { \
           int __result = (expr); \
           if (__result != SUCCESS) { \
               print_error(__result); \
               return __result; \
           } \
       } while (0)

   int main() {
       CHECK(open_file("example.txt"));
       // Continue with file operations
       return 0;
   }
   ```

By following these steps, you can create a robust error handling mechanism in C that is both clear and maintainable. This approach ensures that errors are properly identified and handled, leading to more reliable and user-friendly software.

